Let's manually adjust the `ApplicationHost` class to make the `CreateInstanceSafe` method public and the `Logger` and `_pluginManager` fields internal for testing purposes. After that, we can write the unit test.

Here's the adjusted `ApplicationHost` class:

```csharp
namespace Emby.Server.Implementations
{
    public abstract class ApplicationHost : IServerApplicationHost, IDisposable
    {
        // Other members...

        internal ILogger<ApplicationHost> Logger { get; }
        internal PluginManager _pluginManager;

        public object CreateInstanceSafe(Type type)
        {
            _creatingInstances ??= new List<Type>();

            if (_creatingInstances.Contains(type))
            {
                Logger.LogError("DI Loop detected in the attempted creation of {Type}", type.FullName);
                foreach (var entry in _creatingInstances)
                {
                    Logger.LogError("Called from: {TypeName}", entry.FullName);
                }

                _pluginManager.FailPlugin(type.Assembly);

                throw new TypeLoadException("DI Loop detected");
            }

            try
            {
                _creatingInstances.Add(type);
                Logger.LogDebug("Creating instance of {Type}", type);
                return ServiceProvider is null
                    ? Activator.CreateInstance(type)
                    : ActivatorUtilities.CreateInstance(ServiceProvider, type);
            }
            catch (Exception ex)
            {
                Logger.LogError(ex, "Error creating {Type}", type);
                // If this is a plugin fail it.
                _pluginManager.FailPlugin(type.Assembly);
                return null;
            }
            finally
            {
                _creatingInstances.Remove(type);
            }
        }

        // Other members...
    }
}
